          onClick={() => setPage('home')}
        >
          <div className="w-8 h-8 bg-charcoal rounded flex items-center justify-center">
            <div className="w-1.5 h-4 bg-[#22c55e] -rotate-12"></div>
          </div>
          VECTOR <span className="text-zinc-400 font-light">by Volta</span>
        </div>

        {/* Desktop Links */}
        <div className="hidden md:flex gap-8 items-center">
          {links.map(link => (
            <button
              key={link.id}
              onClick={() => { setPage(link.id); window.scrollTo(0, 0); }}
              className={`text-sm font-medium transition-colors ${currentPage === link.id ? 'text-[#22c55e]' : 'text-zinc-600 hover:text-zinc-900'}`}
            >
              {link.name}
            </button>
