// --- Navigation ---
const Navbar = ({ currentPage, setPage }: { currentPage: string, setPage: (p: string) => void }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const links = [
    { name: 'Home', id: 'home' },
    { name: 'Services', id: 'services' },
    { name: 'Pricing', id: 'pricing' },
    { name: 'About', id: 'about' },
    { name: 'Contact', id: 'contact' },
  ];

  return (
    <nav className={cn(
      "fixed top-0 w-full z-[100] transition-all duration-500",
      scrolled ? "bg-white/80 backdrop-blur-xl border-b border-zinc-100 py-3 shadow-sm" : "bg-transparent py-6"
    )}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        <div 
          className="text-2xl font-black tracking-tighter cursor-pointer flex items-center gap-2"
          onClick={() => { setPage('home'); window.scrollTo({ top: 0, behavior: 'smooth' }); }}
        >
          <div className="w-10 h-10 bg-[#121212] rounded-xl flex items-center justify-center">
            <div className="w-1.5 h-5 bg-[#22c55e] -rotate-12"></div>
          </div>
          <span className="text-[#121212]">VECTOR</span> 
          <span className="text-zinc-400 font-normal">by Volta</span>
        </div>

        <div className="hidden md:flex gap-10 items-center">
          {links.map(link => (
            <button
              key={link.id}
              onClick={() => { setPage(link.id); window.scrollTo({ top: 0, behavior: 'smooth' }); }}
              className={cn(
                "text-[15px] font-bold transition-all duration-300",
                currentPage === link.id ? "text-[#22c55e]" : "text-zinc-600 hover:text-[#121212]"
              )}
            >
              {link.name}
            </button>
          ))}
          <button 
            onClick={() => { setPage('contact'); window.scrollTo({ top: 0, behavior: 'smooth' }); }}
            className="bg-[#121212] text-white px-7 py-3 rounded-full font-bold text-sm tracking-tight transition-all hover:bg-[#22c55e] hover:shadow-lg hover:shadow-green-500/20"
          >
            Book Strategy Call
          </button>
        </div>

        <button className="md:hidden p-2 text-zinc-900" onClick={() => setIsOpen(!isOpen)}>
          {isOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      <AnimatePresence>
        {isOpen && (
          <motion.div 
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="md:hidden absolute top-full left-0 w-full bg-white border-b border-zinc-100 overflow-hidden"
          >
            <div className="p-8 flex flex-col gap-6">
              {links.map(link => (
                <button
                  key={link.id}
                  onClick={() => { setPage(link.id); setIsOpen(false); window.scrollTo({ top: 0, behavior: 'smooth' }); }}
                  className="text-left text-2xl font-black text-zinc-900"
                >
                  {link.name}
                </button>
              ))}
              <button 
                onClick={() => { setPage('contact'); setIsOpen(false); window.scrollTo({ top: 0, behavior: 'smooth' }); }}
                className="w-full bg-[#22c55e] text-white py-5 rounded-2xl font-bold mt-4"
              >
                Book Strategy Call
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
};

