  const [formData, setFormData] = useState({ name: '', goals: '' });
  const [insights, setInsights] = useState<string[]>([]);

  const handleGetStrategy = async () => {
    if (!formData.name || !formData.goals) return;
    setLoading(true);
    const result = await getStrategyInsight(formData.name, formData.goals);
    setInsights(result);
    setLoading(false);
    setStep(2);
  };

  const resetModal = () => {
    setStep(1);
    setFormData({ name: '', goals: '' });
    setInsights([]);
    onClose();
  };

  return (
    <AnimatePresence>
