const BookingModal = ({ isOpen, onClose }: { isOpen: boolean, onClose: () => void }) => {
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({ name: '', goals: '', email: '' });
  const [insights, setInsights] = useState<string[]>([]);
  const [selectedTime, setSelectedTime] = useState('');

  const handleGetStrategy = async () => {
    if (!formData.name || !formData.goals) return;
    setLoading(true);
    const result = await getStrategyInsight(formData.name, formData.goals);
    setInsights(result);
    setLoading(false);
    setStep(2);
  };

  const handleFinalizeBooking = async (time: string) => {
    setSelectedTime(time);
    setLoading(true);

    try {
      if (EMAILJS_PUBLIC_KEY !== 'YOUR_PUBLIC_KEY') {
        await emailjs.send(
          EMAILJS_SERVICE_ID,
          EMAILJS_TEMPLATE_ID,
          {
            from_name: formData.name,
            from_email: formData.email,
            message: `Strategic Goals: ${formData.goals}. Preferred Time: ${time}. Insights Generated: ${insights.join(', ')}`,
          },
          EMAILJS_PUBLIC_KEY
        );
      } else {
        await new Promise(resolve => setTimeout(resolve, 1500));
        console.log("Email simulation complete (Public Key not provided). Payload:", {
            business: formData.name,
            goals: formData.goals,
            time: time,
            insights: insights
        });
      }
    } catch (error) {
      console.error("Email failed:", error);
    }

    setLoading(false);
    setStep(3);
  };

  const resetModal = () => {
    setStep(1);
    setFormData({ name: '', goals: '', email: '' });
    setInsights([]);
    setSelectedTime('');
    onClose();
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }}
            onClick={resetModal}
            className="absolute inset-0 bg-[#121212]/95 backdrop-blur-xl"
