const BookingModal = ({ isOpen, onClose }: { isOpen: boolean, onClose: () => void }) => {
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({ name: '', goals: '', email: '' });
  const [insights, setInsights] = useState<string[]>([]);
  const [selectedTime, setSelectedTime] = useState('');

  const handleGetStrategy = async () => {
    if (!formData.name || !formData.goals) return;
    setLoading(true);
    const result = await getStrategyInsight(formData.name, formData.goals);
    setInsights(result);
    setLoading(false);
    setStep(2);
  };

  const handleFinalizeBooking = async (time: string) => {
    setSelectedTime(time);
    setLoading(true);

    const templateParams = {
      from_name: formData.name,
      from_email: formData.email,
      message: `BOOKING REQUEST:
Preferred Time: ${time}
Client Goals: ${formData.goals}
AI Insights Provided: ${insights.join(' | ')}`
    };

    try {
      await emailjs.send(
        EMAILJS_SERVICE_ID,
        EMAILJS_TEMPLATE_ID,
        templateParams,
        EMAILJS_PUBLIC_KEY
      );
      setStep(3);
    } catch (error) {
      console.error("Booking Error:", error);
      alert("Failed to send booking. Please verify your EmailJS connection.");
    } finally {
      setLoading(false);
    }
  };

  const resetModal = () => {
    setStep(1);
    setFormData({ name: '', goals: '', email: '' });
    setInsights([]);
    setSelectedTime('');
    onClose();
